print(h.status.value_counts())
ent={e:i for e,i in zip(h.entrez_id,h.hgnc_id) if isinstance(e,str)}
ens={e:i for e,i in zip(h.ensembl_gene_id,h.hgnc_id) if isinstance(e,str)}
sym={s:i for s,i in zip(h.symbol,h.hgnc_id)}
prev={};ali={}
for s,p,a,i in zip(h.symbol,h.prev_symbol,h.alias_symbol,h.hgnc_id):
    for col,dd in ((p,prev),(a,ali)):
        if isinstance(col,str):
            for x in col.split('|'): dd.setdefault(x,set()).add(i)
def mapsym(s):
    if s in sym: return sym[s]
    if s in prev and len(prev[s])==1: return next(iter(prev[s]))
    if s in ali and len(ali[s])==1: return next(iter(ali[s]))
    return None
rs={}
for r,i in zip(h.refseq_accession,h.hgnc_id):
    if isinstance(r,str):
        for x in r.split('|'): rs[x]=i
def ids_in_matrix(f):
    with gzip.open(R+f,'rt') as fh: L=fh.read().splitlines()
    i=[k for k,l in enumerate(L) if l.startswith('!series_matrix_table_begin')][0]
    df=pd.read_csv(io.StringIO('\n'.join(L[i+1:-1])),sep='\t')
    return df
